draftBody:
export default async (): Promise<RequestMessage> => (
{
  collection: "example",
  // `requestId` and `stamp` are this collection's own GENERATOR scripts, bound
  // as globals under their script names. Only the ones a body actually calls
  // are pulled into the sandbox.
  //
  // JSON.stringify turns the generated text into a quoted string literal, so
  // the scratchpad grpcview runs is a single expression and its value comes
  // straight back in the response.
  source: JSON.stringify(`${requestId("gv")} at ${stamp()}`),
}
)

draftMetadataScript:
export default async (): Promise<Metadata> => (
{
  // Metadata is the same language as the body, evaluated to a
  // { [key: string]: string[] } map. Spread the folder chain first, then add
  // the per-request headers — dropping the spread would discard them.
  ...gv.metadata.inherit(),
  "x-request-id": [requestId()],
  "x-sent-at": [stamp()],
}
)
